export function wakesOn(text) {
  let t = String(text || '');
  for (const re of IDIOMS) t = t.replace(re, ' ');
  return { intimate: acted(INTIMACY_RE, t) || acted(INTIMACY_MORE_RE, t), fight: acted(COMBAT_RE, t) || acted(FIGHT_MORE_RE, t) || acted(FIGHT_PHRASE_RE, t) };
}
